export function resolvePermissions(role: string, parents: Record<string, string>, grants: Record<string, string[]>): string[] | null {
  const result: string[] = [];
  const visited = new Set<string>();
  const queue: string[] = [];

  // Handle empty parent (root)
  if (parents[role] === "") {
    return result;
  }

  // Check for unknown role
  if (!parents[role]) {
    return null;
  }

  // Start with the role's grants
  const roleGrants = grants[role] || [];
  for (const grant of roleGrants) {
    if (visited.has(grant)) continue;
    visited.add(grant);
    result.push(grant);
    queue.push(grant);
  }

  // Process queue
  while (queue.length > 0) {
    const parent = queue.shift()!;
    if (visited.has(parent)) continue;
    visited.add(parent);

    // Check for unknown parent
    if (!parents[parent]) {
      return null;
    }

    // Collect parent's grants
    const parentGrants = grants[parent] || [];
    for (const grant of parentGrants) {
      if (visited.has(grant)) continue;
      visited.add(grant);
      result.push(grant);
      queue.push(grant);
    }
  }

  // Check for inheritance cycle
  if (visited.has(role)) {
    return null;
  }

  return result;
}

